function opsRoutes(iata, rt, keys, starTo){
  const def = OPS_AIRPORTS[iata], use = {}, all = { ...keys.a, ...keys.b }, appKey = {};
  for(const [m, op] of Object.entries(def.modes)){ use[m] = {}; for(const r of op.dep) if(rt.sid[r]) use[m][r] = Object.keys(rt.sid[r]);
    // 着陸と離陸で逆の向きを使う運用（仙台・松山）も、着陸する滑走路の進入を使う
    const k = Object.fromEntries(op.arr.filter(r => all[r]).map(r => [r, all[r]])); appKey[m] = { good:k, bad:k }; }
  Object.assign(def, { app:rt.app, star:rt.star, sid:rt.sid, sidUse:use, appKey, starTo });
}
