OPS_AIRPORTS.FUK.pref = { mode:"a", tail:10 };
// 仙台・松山は「着陸と離陸で逆の向きを使う」優先滑走路方式がある（AD 2.21。追い風5kt・横風15kt を超えるときは使わない）。
//   仙台：着陸は27、離陸は09（海側へ出入りする）。松山：着陸は14、離陸は32（海側へ出入りする）
for(const [iata, arr, dep, dirA, dirD] of [["SDJ", "27", "09", "西向き", "東向き"], ["MYJ", "14", "32", "南東向き", "北西向き"]]){
  const d = OPS_AIRPORTS[iata];
  d.modes.p = { label:`${arr}着陸・${dep}離陸（優先方式）`, arr:[arr], dep:[dep], note:`着陸は${arr}（${dirA}）、離陸は${dep}（${dirD}）と、着陸と離陸で逆の向きを使います（騒音を減らすための優先滑走路方式）。` };
  d.split = { mode:"p", tail:5, cross:15 };
}
